import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageClasses() {
  const [classes, setClasses] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  
  const [formData, setFormData] = useState({ day: 'Monday', grade: '', subject_id: '', time_slot: '', teacher_id: '' });

  const fetchClasses = () => axios.get('http://localhost:8081/api/timetable').then(res => setClasses(res.data));
  
  useEffect(() => { 
      fetchClasses(); 
      axios.get('http://localhost:8081/api/view-teachers').then(res => setTeachers(res.data));
      axios.get('http://localhost:8081/api/view-subjects').then(res => setSubjects(res.data));
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/timetable', formData).then(() => { 
        fetchClasses(); 
        setShowForm(false);
        setFormData({ day: 'Monday', grade: '', subject_id: '', time_slot: '', teacher_id: '' });
        alert("✅ Class Added Successfully!");
    }).catch(err => alert("Error adding class!"));
  };

  const handleDelete = (id) => { 
      if(window.confirm("Are you sure you want to delete this class?")) {
          axios.delete(`http://localhost:8081/api/timetable/${id}`).then(() => fetchClasses()); 
      }
  };

  // Search කිරීම සඳහා
  const filteredClasses = classes.filter(c => 
    c.day.toLowerCase().includes(searchQuery.toLowerCase()) || 
    c.grade.toLowerCase().includes(searchQuery.toLowerCase()) ||
    c.subject.toLowerCase().includes(searchQuery.toLowerCase()) ||
    c.teacher.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div style={{ padding: '10px', fontFamily: 'sans-serif', animation: 'fadeIn 0.5s' }}>
      
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', backgroundColor: '#fff', padding: '15px 20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.02)' }}>
        <h2 style={{ margin: 0, color: '#1e293b' }}>📅 Manage Classes (Timetable)</h2>
        <div style={{ display: 'flex', gap: '15px' }}>
          <input 
            type="text" 
            placeholder="Search by Day, Grade or Subject..." 
            value={searchQuery} 
            onChange={(e) => setSearchQuery(e.target.value)} 
            style={{ padding: '8px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', width: '250px' }} 
          />
          <button onClick={() => setShowForm(true)} style={{ padding: '8px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>
            + Add Class
          </button>
        </div>
      </div>

      <div style={{ backgroundColor: '#fff', borderRadius: '12px', overflow: 'hidden', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
              <th style={thStyle}>Day</th>
              <th style={thStyle}>Time</th>
              <th style={thStyle}>Grade</th>
              <th style={thStyle}>Subject</th>
              <th style={thStyle}>Teacher</th>
              <th style={{...thStyle, textAlign: 'center'}}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredClasses.length > 0 ? filteredClasses.map((c) => (
              <tr key={c.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={{...tdStyle, fontWeight: 'bold', color: '#15803d'}}>{c.day}</td>
                <td style={{...tdStyle, color: '#eab308', fontWeight: 'bold'}}>{c.time_slot}</td>
                <td style={tdStyle}>{c.grade}</td>
                <td style={{...tdStyle, fontWeight: 'bold', color: '#0369a1'}}>{c.subject}</td>
                <td style={tdStyle}>{c.teacher}</td>
                <td style={{...tdStyle, textAlign: 'center'}}>
                  <button onClick={() => handleDelete(c.id)} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: '16px' }}>🗑️</button>
                </td>
              </tr>
            )) : <tr><td colSpan="6" style={{ padding: '30px', textAlign: 'center', color: '#94a3b8' }}>No classes scheduled yet.</td></tr>}
          </tbody>
        </table>
      </div>

      {showForm && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', width: '450px', boxShadow: '0 10px 25px rgba(0,0,0,0.1)' }}>
            <h3 style={{ margin: '0 0 20px 0', color: '#1e293b', borderBottom: '1px solid #f1f5f9', paddingBottom: '10px' }}>➕ Add New Class</h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              
              <select value={formData.day} onChange={(e) => setFormData({...formData, day: e.target.value})} style={inputStyle} required>
                <option value="Monday">Monday</option><option value="Tuesday">Tuesday</option><option value="Wednesday">Wednesday</option><option value="Thursday">Thursday</option><option value="Friday">Friday</option><option value="Saturday">Saturday</option><option value="Sunday">Sunday</option>
              </select>
              
              <input type="text" placeholder="Grade (e.g. Grade 10, 2026 Revision)" value={formData.grade} onChange={(e) => setFormData({...formData, grade: e.target.value})} required style={inputStyle} />
              <input type="text" placeholder="Time (e.g. 03:00 PM - 05:00 PM)" value={formData.time_slot} onChange={(e) => setFormData({...formData, time_slot: e.target.value})} required style={inputStyle} />
              
              {/* මෙතන s.Id කියලා වෙනස් කළා Database එකට ගැලපෙන්න */}
              <select value={formData.subject_id} onChange={(e) => setFormData({...formData, subject_id: e.target.value})} style={inputStyle} required>
                <option value="">-- Select Subject --</option>
                {subjects.map(s => <option key={s.Id || s.id} value={s.Id || s.id}>{s.subject_name}</option>)}
              </select>

              <select value={formData.teacher_id} onChange={(e) => setFormData({...formData, teacher_id: e.target.value})} style={inputStyle} required>
                <option value="">-- Select Teacher --</option>
                {teachers.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
              </select>
              
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '10px' }}>
                <button type="button" onClick={() => setShowForm(false)} style={{ padding: '10px 15px', borderRadius: '8px', border: 'none', backgroundColor: '#f1f5f9', color: '#475569', cursor: 'pointer', fontWeight: 'bold' }}>Cancel</button>
                <button type="submit" style={{ padding: '10px 20px', backgroundColor: '#15803d', color: 'white', borderRadius: '8px', border: 'none', cursor: 'pointer', fontWeight: 'bold' }}>Save Class</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

const inputStyle = { padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', width: '100%', boxSizing: 'border-box', outline: 'none', fontSize: '14px' };
const thStyle = { padding: '12px 15px', fontSize: '14px', textAlign: 'left', color: '#475569', whiteSpace: 'nowrap' };
const tdStyle = { padding: '12px 15px', fontSize: '14px', color: '#333' };
